    grid-column: 2;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    color: #e0e0e0;
}

label a {
    color: #4a9eff;
    text-decoration: underline;
    transition: color 0.2s ease;
}

label a:hover {
    color: #6bb3ff;
}

label a:focus-visible {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

.required-indicator {
    color: #ff6b6b;
    font-weight: 600;
}

.helper-text {
    grid-column: 2;
    font-size: 14px;
    color: #b0b0b0;
    margin-top: -4px;
}

.error-text {
    grid-column: 1 / -1;
    font-size: 14px;
    color: #ff6b6b;
    margin-top: 4px;
}

.submit-button {
    background-color: #4a9eff;
    color: #ffffff;
    border: none;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 8px;
}

.submit-button:hover:not(:disabled) {
    background-color: #3a8eef;
    box-shadow: 0 4px 12px rgba(74, 158, 255, 0.3);
}

.submit-button:focus-visible {
    outline: 3px solid #4a9eff;
    outline-offset: 2px;
}

.submit-button:active:not(:disabled) {
    background-color: #2a7edf;
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

