const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const filePath = path.join(__dirname, "index.html");
    const html = fs.readFileSync(filePath, "utf-8");

    // Create temporary HTML file with axe injected
    const axeMinJS = fs.readFileSync(require.resolve("axe-core/axe.min.js"), "utf-8");
    const testHtml = html.replace("</html>", `<script>${axeMinJS}</script></html>`);
    const tempPath = path.join(__dirname, "temp-test.html");
    fs.writeFileSync(tempPath, testHtml);

    try {
        await page.goto(`file://${tempPath}`, { waitUntil: "load" });

        // Check if axe is loaded
        const axeReady = await page.evaluate("() => typeof window.axe");
        console.log("Axe ready:", axeReady);

        if (axeReady !== "undefined") {
            // Run axe
            const results = await page.evaluate("async () => await window.axe.run()");

            // Separate WCAG violations from best-practice
            const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
            const bp = results.violations.filter(v => v.tags.includes("best-practice"));

            const output = {
                wcag: wcag.map(v => ({
                    id: v.id,
                    impact: v.impact,
                    targets: v.nodes.map(n => n.target),
                    description: v.description
                })),
                bp: bp.map(v => ({
                    id: v.id,
                    targets: v.nodes.map(n => n.target),
                    description: v.description
                }))
            };

            console.log(JSON.stringify(output, null, 2));
            process.exit(wcag.length > 0 ? 1 : 0);
        } else {
            console.error("Axe failed to load");
            process.exit(1);
        }
    } finally {
        fs.unlinkSync(tempPath);
        await browser.close();
