const { JSDOM } = require("jsdom");
const fs = require("fs");
const path = require("path");
const axeCore = require("axe-core");

(async () => {
    const filePath = path.join(__dirname, "index.html");
    const html = fs.readFileSync(filePath, "utf-8");

    const dom = new JSDOM(html, {
        url: "file://" + filePath,
        pretendToBeVisual: true
    });

    const { window } = dom;

    // Execute axe source in window context
    const script = window.document.createElement("script");
    script.textContent = axeCore.source;
    window.document.head.appendChild(script);

    // Wait a moment for script to execute
    await new Promise(resolve => setTimeout(resolve, 100));

    // Check if axe is loaded
    if (!window.axe) {
        console.error("Axe failed to load");
        process.exit(1);
    }

    // Run axe
    const results = await window.axe.run(window.document);

    // Separate WCAG violations from best-practice
    const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
    const bp = results.violations.filter(v => v.tags.includes("best-practice"));

    const output = {
        wcag: wcag.map(v => ({
            id: v.id,
            impact: v.impact,
            targets: v.nodes.map(n => n.target),
            description: v.description
        })),
        bp: bp.map(v => ({
            id: v.id,
            targets: v.nodes.map(n => n.target),
            description: v.description
        }))
    };

    console.log(JSON.stringify(output, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF
