const { JSDOM } = require("jsdom");
const fs = require("fs");
const path = require("path");
const axeCore = require("axe-core");

(async () => {
    const filePath = path.join(__dirname, "index.html");
    const html = fs.readFileSync(filePath, "utf-8");

    const dom = new JSDOM(html, {
        url: "file://" + filePath,
        pretendToBeVisual: true
    });

    const { window } = dom;
    const { document } = window;

    try {
        // Execute axe using the function wrapper directly
        new Function(axeCore.source)(window);
        console.log("Axe source executed");
        console.log("window.axe exists?", !!window.axe);
    } catch(e) {
        console.error("Error loading axe:", e.message);
    }

    // Check if axe is loaded
    if (!window.axe) {
        console.error("Axe is undefined after execution");
        console.log("Available in window:", Object.keys(window).filter(k => k.toLowerCase().includes('axe')));
        process.exit(1);
    }

    // Run axe
    const results = await window.axe.run(document);

    // Separate WCAG violations from best-practice
    const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
    const bp = results.violations.filter(v => v.tags.includes("best-practice"));

    const output = {
        wcag: wcag.map(v => ({
            id: v.id,
            impact: v.impact,
            targets: v.nodes.map(n => n.target),
            description: v.description
        })),
        bp: bp.map(v => ({
            id: v.id,
            targets: v.nodes.map(n => n.target),
            description: v.description
        }))
    };

    console.log(JSON.stringify(output, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF
