    display: flex;
    align-items: center;
    gap: 6px;
    color: #e0e0e0;
}

label a {
    color: #4a9eff;
    text-decoration: underline;
    transition: color 0.2s ease;
}

label a:hover {
    color: #6bb3ff;
}

label a:focus-visible {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

.required-indicator {
    color: #ff6b6b;
