}

/* Ensure checkbox is properly aligned in grid */
input[type="checkbox"] {
    grid-column: 1;
    grid-row: 1;
}

/* Responsive design */
@media (max-width: 480px) {
    .container {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
        margin-bottom: 24px;
    }

    form {
        gap: 20px;
    }

    .submit-button {
        padding: 12px 20px;
        font-size: 15px;
    }
}

/* High contrast / forced colors support */
@media (forced-colors: active) {
    .container {
        border-color: CanvasText;
