        outline-color: LinkText;
    }

    label a:focus-visible {
        outline-color: LinkText;
    }

    .submit-button:focus-visible {
        outline-color: LinkText;
    }
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
    * {
        transition: none !important;
        animation: none !important;
    }
}
